List<Integer> xs = new List<Integer>{1, 2};
System.assert(!xs.isEmpty());
xs.add(3);
xs.add(1, 9);
System.assertEquals(4, xs.size());
System.assertEquals(9, xs.get(1));
System.assertEquals(1, xs.indexOf(9));
System.assertEquals(-1, xs.indexOf(99));
System.assertEquals(9, xs.remove(1));
xs.set(0, 7);
xs.addAll(new List<Integer>{8, 9});
System.assertEquals(7, xs.get(0));
System.assertEquals(9, xs.get(xs.size() - 1));
List<Integer> copiedXs = new List<Integer>(xs);
copiedXs.sort();
System.assertEquals(2, copiedXs.get(0));
List<Integer> clonedXs = copiedXs.clone();
clonedXs.set(0, 99);
System.assertEquals(2, copiedXs.get(0));
List<Integer> deepXs = copiedXs.deepClone();
deepXs.set(1, 88);
System.assertEquals(3, copiedXs.get(1));
Iterator<Integer> intIt = copiedXs.iterator();
System.assert(intIt.hasNext());
System.assertEquals(2, intIt.next());
System.assertEquals(3, intIt.next());
System.assertEquals(7, intIt.next());
System.assertEquals(8, intIt.next());
System.assertEquals(9, intIt.next());
System.assert(!intIt.hasNext());
xs.clear();
System.assert(xs.isEmpty());
Set<String> names = new Set<String>{'a'};
System.assert(!names.isEmpty());
System.assert(names.add('b'));
System.assert(!names.add('b'));
System.assert(names.containsAll(new List<String>{'a', 'b'}));
System.assert(names.remove('a'));
System.assert(!names.contains('a'));
System.assert(names.addAll(new List<String>{'c', 'd'}));
System.assert(names.removeAll(new Set<String>{'b'}));
System.assert(names.retainAll(new List<String>{'c'}));
Set<String> copiedNames = new Set<String>(new List<String>{'c', 'c', 'e'});
System.assertEquals(2, copiedNames.size());
Set<String> clonedNames = copiedNames.clone();
clonedNames.add('f');
System.assertEquals(2, copiedNames.size());
Set<String> deepNames = copiedNames.deepClone();
deepNames.remove('c');
System.assert(copiedNames.contains('c'));
Iterator<String> nameIt = copiedNames.iterator();
System.assert(nameIt.hasNext());
System.assertEquals('c', nameIt.next());
System.assertEquals('e', nameIt.next());
System.assert(!nameIt.hasNext());
System.assertEquals(1, names.size());
names.clear();
System.assert(names.isEmpty());
Map<String,Integer> counts = new Map<String,Integer>();
System.assert(counts.isEmpty());
System.assertEquals(null, counts.put('a', 1));
System.assertEquals(1, counts.put('a', 2));
System.assert(counts.containsKey('a'));
System.assert(counts.containsValue(2));
Set<String> keys = counts.keySet();
System.assert(keys.contains('a'));
List<Integer> vals = counts.values();
System.assert(vals.contains(2));
Map<String,Integer> moreCounts = new Map<String,Integer>();
moreCounts.put('b', 3);
counts.putAll(moreCounts);
System.assertEquals(3, counts.get('b'));
Map<String,Integer> copiedCounts = new Map<String,Integer>(counts);
System.assertEquals(counts, copiedCounts);
System.assertEquals('Map{a=2, b=3}', copiedCounts.toString());
Map<String,Integer> clonedCounts = copiedCounts.clone();
clonedCounts.put('a', 9);
System.assertEquals(2, copiedCounts.get('a'));
Map<String,Integer> deepCounts = copiedCounts.deepClone();
deepCounts.put('b', 8);
System.assertEquals(3, copiedCounts.get('b'));
System.assertEquals(2, counts.remove('a'));
System.assertEquals(null, counts.remove('missing'));
counts.clear();
System.assert(counts.isEmpty());
System.assert(!counts.containsKey('b'));
List<String> nullWords = new List<String>{null, 'a', null};
System.assert(nullWords.contains(null));
System.assertEquals(0, nullWords.indexOf(null));
System.assertEquals(null, nullWords.remove(0));
Set<String> nullNames = new Set<String>{null, 'a', null};
System.assert(nullNames.contains(null));
System.assert(!nullNames.add(null));
System.assert(nullNames.remove(null));
Map<String,String> nullMap = new Map<String,String>();
nullMap.put(null, 'nil');
nullMap.put('blank', null);
System.assert(nullMap.containsKey(null));
System.assert(nullMap.containsValue(null));
Set<String> nullKeys = nullMap.keySet();
System.assert(nullKeys.contains(null));
System.assertEquals('nil', nullMap.get(null));
System.assertEquals(null, nullMap.remove('blank'));
Account acme = new Account(Id = '001B000001DVM9tIAH', Name = 'Acme');
Account beta = new Account(Id = '001B000001DVM9uIAH', Name = 'Beta');
Map<Id, Account> accountsById = new Map<Id, Account>(new List<Account>{acme, beta});
System.assertEquals(2, accountsById.size());
Account fromAccountsById = accountsById.get(acme.Id);
System.assertEquals('Acme', fromAccountsById.Name);
Map<Id, Account> moreAccountsById = new Map<Id, Account>();
moreAccountsById.putAll(new List<Account>{beta});
Account fromMoreAccountsById = moreAccountsById.get(beta.Id);
System.assertEquals('Beta', fromMoreAccountsById.Name);

